export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;
const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;

const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

/** Rounds to whole G in the MHPCO's favour. */
const roundUpToWholeG = (amount: number): number => Math.ceil(amount);

const quotePremium = (items: Item[]): number => {
  const policyBasePremium = items.reduce((sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type], 0);
  const initialAssessmentSurcharge = policyBasePremium * INITIAL_ASSESSMENT_SURCHARGE_RATE;
  return roundUpToWholeG(policyBasePremium + initialAssessmentSurcharge + PROCESSING_FEE);
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  return {
    results: scenario.steps.map((step) => ({
      premium: quotePremium((step as QuoteStep).items),
    })),
  };
};

