import { describe, it, expect } from "vitest";
import { runScenario, type Scenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — base premiums", () => {
    it("empty item list → premium 5 G (only the processing fee)", () => {
      const scenario: Scenario = {
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [] }],
      };

      expect(runScenario(scenario)).toEqual({ results: [{ premium: 5 }] });
    });
    // premium = base + 10 % initial assessment surcharge + 5 G processing fee
    it.each([
      { type: "sword", base: 100, premium: 115 },
      { type: "amulet", base: 60, premium: 71 },
      { type: "staff", base: 80, premium: 93 },
      { type: "potion", base: 40, premium: 49 },
      { type: "rune", base: 25, premium: 33 },
      { type: "moonstone", base: 25, premium: 33 },
    ])("a single $type → base premium $base G", ({ type, premium }) => {
      const scenario: Scenario = {
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type }] }],
      };

      expect(runScenario(scenario)).toEqual({ results: [{ premium }] });
    });
  });

  describe("quote — building block of 3 alike components", () => {
    it("2 runes → 50 G base premium", () => {
      const scenario: Scenario = {
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
      };

      // 2 × 25 = 50 base (no block: requires exactly 3)
      // 50 + 5 initial assessment = 55, + 5 fee = 60
      expect(runScenario(scenario)).toEqual({ results: [{ premium: 60 }] });
    });
    it("3 runes → 60 G base premium (block applies)", () => {
      const scenario: Scenario = {
        customer: { yearsWithMHPCO: 0 },
        steps: [
          { op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }] },
        ],
      };

      // block of 3 alike components → 60 base (not 3 × 25 = 75)
      // 60 + 6 initial assessment = 66, + 5 fee = 71
      expect(runScenario(scenario)).toEqual({ results: [{ premium: 71 }] });
    });
    it("4 runes → 100 G base premium (no block — block requires exactly 3)", () => {
      const scenario: Scenario = {
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: Array.from({ length: 4 }, () => ({ type: "rune" })) }],
      };

      // 4 × 25 = 100 base (the block does not apply to a subset of 3)
      // 100 + 10 initial assessment = 110, + 5 fee = 115
      expect(runScenario(scenario)).toEqual({ results: [{ premium: 115 }] });
    });
    it("7 runes → 175 G base premium", () => {
      const scenario: Scenario = {
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: Array.from({ length: 7 }, () => ({ type: "rune" })) }],
      };

      // 7 × 25 = 175 base (the block does not repeat: not 2 blocks + 1)
      // 175 + 17.5 initial assessment = 192.5, + 5 fee = 197.5 → rounds up to 198
      expect(runScenario(scenario)).toEqual({ results: [{ premium: 198 }] });
    });
    it("2 runes + 1 moonstone → 75 G base premium (no block: different types)", () => {
      const scenario: Scenario = {
        customer: { yearsWithMHPCO: 0 },
        steps: [
          {
            op: "quote",
            items: [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }],
          },
        ],
      };

      // Pins "alike" = the SAME TYPE, not the same family: 3 components but
      // no block, because the rune group is 2 and the moonstone group is 1.
      // 3 × 25 = 75 base; 75 + 7.5 = 82.5, + 5 fee = 87.5 → rounds up to 88
      expect(runScenario(scenario)).toEqual({ results: [{ premium: 88 }] });
    });
    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
  });

  describe("quote — item-specific modifiers", () => {
    it.todo("cursed sword → 50 % risk surcharge on that item's base premium");
    it.todo("sword with enchantment 5 → 30 % high-enchantment surcharge applies");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge");
    it.todo("cursed sword with enchantment 5 → both surcharges apply");
  });

  describe("quote — policy-wide modifiers", () => {
    it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
    it.todo("customer with 1 year with MHPCO → no loyalty discount");
    it.todo("first insurance → 10 % initial assessment surcharge on the policy base premium");
    it.todo("the customer's second quote → additional 15 % follow-up contract discount");
  });

  describe("quote — modifier scope on multi-item policies", () => {
    it.todo(
      "cursed sword (100 G) + plain amulet (60 G) → policy base 160 G; curse adds 50 G (50 % of the cursed item only) → 210 G before further modifiers and fee",
    );
  });

  describe("quote — rounding in the MHPCO's favour", () => {
    it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
    it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
  });

  describe("claim — standard reimbursement", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
    it.todo("damage to a rune (no enchantment or material), damage 200 G → payout 100 G");
  });

  describe("claim — special clauses", () => {
    it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (dragon clause only)");
    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % clause, then deductible)");
    it.todo("dragon-material sword, enchantment 8, damage 1000 G → payout 400 G (50 % clause at the threshold)");
    it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins over dragon material)");
  });

  describe("claim — deductible per damage event", () => {
    it.todo(
      "a dragon attack damages a sword (500 G) and an amulet (300 G) → payout 600 G (100 G deductible once per damaged item)",
    );
    it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
  });

  describe("claim — insurance sum and cap", () => {
    it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
    it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
    it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G, cap 3500 G (block affects premium only)");
    it.todo("a cursed sword → cap 2000 G based on the unmodified insurance value (premium modifiers do not raise the cap)");
    it.todo("sword (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
    it.todo("sword (cap 2000 G), second claim of 1500 G → payout 600 G, remainingCap 0 G (reduced to the remaining cap)");
  });

  describe("claim — multiple items of the same type", () => {
    it.todo(
      "a policy covers two swords; two sword damage entries → each entry is a separate damage with its own deductible",
    );
    it.todo("more damage entries of a type than the policy covers (two sword damages, one sword insured) → error");
  });

  describe("errors", () => {
    it.todo("quote includes an item with an unknown type (e.g. broomstick) → error");
    it.todo("claim references a damage entry whose item is not part of the policy (amulet damaged, only a sword insured) → error");
    it.todo("claim references a damage entry with an unknown item type → error");
    it.todo("claim contains a damage entry with amount -200 → error");
  });

  describe("integration examples", () => {
    it.todo("newcomer (0 years, no previous contract) with a cursed steel sword (enchantment 3) → premium 165 G");
    it.todo("long-standing customer (3 years), second quote, cursed steel sword (enchantment 7) → premium 160 G");
  });
});

