const PROCESSING_FEE = 5;
const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;

const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const COMPONENT_TYPES = ["rune", "moonstone"];
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const sum = (amounts: number[]): number => amounts.reduce((total, a) => total + a, 0);

/** Rounds to whole G in the MHPCO's favour. */
const roundUpToWholeG = (amount: number): number => Math.ceil(amount);

const countByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
};

/**
 * Components are priced per group of alike items, because a building block of
 * exactly 3 alike components earns a special rate. Main items price per item.
 */
const basePremiumForGroup = (type: string, count: number): number => {
  if (COMPONENT_TYPES.includes(type) && count === BLOCK_SIZE) {
    return BLOCK_BASE_PREMIUM;
  }
  return count * BASE_PREMIUM_BY_TYPE[type];
};

const quotePremium = (items: Item[]): number => {
  const policyBasePremium = sum(
    [...countByType(items)].map(([type, count]) => basePremiumForGroup(type, count)),
  );
  const initialAssessmentSurcharge = policyBasePremium * INITIAL_ASSESSMENT_SURCHARGE_RATE;
  return roundUpToWholeG(policyBasePremium + initialAssessmentSurcharge + PROCESSING_FEE);
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  return {
    results: scenario.steps.map((step) => ({
      premium: quotePremium((step as QuoteStep).items),
    })),
  };
};

